mapper.select:
SELECT BOARD_ID, TITLE, CONTENT, REGIST_DT, REGISTER FROM BOARD WHERE BOARD_TYPE = 'FAQ'
AND TITLE LIKE '%' || #{searchKeyword} || '%'
ORDER BY REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.delete:
DELETE FROM BOARD
WHERE BOARD_ID = #{boardId}
	AND BOARD_TYPE = 'FAQ'
